function ThemePicker({ theme, schedule, scheduleTimes, highContrast, background, onChange, onScheduleChange, onScheduleTimesChange, onContrastChange, onBackgroundChange, onClose }: { theme: ThemeId; schedule: ThemeSchedule; scheduleTimes: ThemeScheduleTimes; highContrast: boolean; background: BackgroundId; onChange: (theme: ThemeId) => void; onScheduleChange: (schedule: ThemeSchedule) => void; onScheduleTimesChange: (times: ThemeScheduleTimes) => void; onContrastChange: (active: boolean) => void; onBackgroundChange: (background: BackgroundId) => void; onClose: () => void }) {
  const [preview, setPreview] = useState<ThemeId>(theme);
  const [previewBackground, setPreviewBackground] = useState<BackgroundId>(background);
  const previewOption = themeOptions.find((option) => option.id === preview) || themeOptions[0];
  const scheduleIsValid = timeToMinutes(scheduleTimes.dayStart, -1) < timeToMinutes(scheduleTimes.eveningStart, -1) && timeToMinutes(scheduleTimes.eveningStart, -1) < timeToMinutes(scheduleTimes.nightStart, -1);
  const applyPreview = () => { onChange(preview); onBackgroundChange(previewBackground); onScheduleChange(schedule); onClose(); };
  const dialogRef = useFocusTrap<HTMLElement>(onClose);
  return <div className="bf-modal-backdrop bf-theme-backdrop" role="presentation" onMouseDown={onClose}><section ref={dialogRef} tabIndex={-1} className="bf-modal bf-theme-picker" role="dialog" aria-modal="true" aria-label="Alege aspectul" onMouseDown={(event) => event.stopPropagation()}><header><div><p className="bf-kicker">ASPECTUL APLICAȚIEI</p><h2>Alege o atmosferă, nu doar o culoare.</h2></div><button className="bf-icon-button" aria-label="Închide alegerea temei" onClick={onClose}><X size={19} /></button></header><p className="bf-theme-picker-intro">Previzualizezi înainte de aplicare. Verdele rămâne progres, mierea înseamnă revizuire, iar coralul atrage atenția.</p><section className={`bf-theme-preview ${preview} background-preview-${previewBackground}`} aria-label={`Previzualizare ${previewOption.name}`}><div className="bf-theme-preview-top"><span>{previewOption.mood}</span><b>{previewOption.name}</b></div><div className="bf-theme-preview-value"><small>BANI NEREPARTIZAȚI</small><strong>1.480 RON</strong><i /></div><div className="bf-theme-preview-stats"><span>DISPONIBIL <b>4.830 RON</b></span><span>REZERVAT <b>780 RON</b></span></div><div className="bf-theme-preview-nav"><i /><i /><i /><i /></div></section><p className="bf-theme-preview-note">Aceasta este o previzualizare mare a suprafețelor, cifrelor și navigației; datele tale nu se schimbă până la aplicare.</p><div className="bf-theme-grid">{themeOptions.map((option) => <button key={option.id} className={`bf-theme-option ${option.id} ${preview === option.id ? "selected" : ""}`} aria-pressed={preview === option.id} onClick={() => setPreview(option.id)}><span className="bf-theme-swatch" aria-hidden="true"><span /></span><span><em>{option.mood}</em><b>{option.name}</b><small>{option.detail}</small></span><i>{preview === option.id && <Check size={14} />}</i></button>)}</div><section className="bf-background-preferences" aria-labelledby="bf-background-title"><div><p className="bf-kicker">FUNDAL</p><h3 id="bf-background-title">Alege textura suprafeței</h3><p>Schimbă atmosfera fără să afectezi lizibilitatea datelor.</p></div><div className="bf-background-grid">{backgroundOptions.map((option) => <button key={option.id} className={previewBackground === option.id ? "selected" : ""} aria-pressed={previewBackground === option.id} onClick={() => setPreviewBackground(option.id)}><span className={`bf-background-swatch ${option.id}`} aria-hidden="true" /><b>{option.name}</b><small>{option.detail}</small></button>)}</div></section><section className="bf-theme-preferences" aria-label="Preferințe temă"><button className={schedule === "auto" ? "active" : ""} role="switch" aria-checked={schedule === "auto"} onClick={() => onScheduleChange(schedule === "auto" ? "manual" : "auto")}><span><b>Comută automat zi/noapte</b><small>{schedule === "auto" ? `Activ acum: ${themeOptions.find((item) => item.id === automaticTheme(currentLocalMinutes(), scheduleTimes))?.name || "tema automată"}. Zi ${scheduleTimes.dayStart}–${scheduleTimes.eveningStart} · seară ${scheduleTimes.eveningStart}–${scheduleTimes.nightStart} · noapte ${scheduleTimes.nightStart}–${scheduleTimes.dayStart}.` : "Folosește Porcelain ziua, Aurora seara și Ultraviolet noaptea."}</small></span><i aria-hidden="true" /></button><div className="bf-theme-schedule-fields" aria-label="Intervale automate"><label><span>Ziua începe</span><input type="time" value={scheduleTimes.dayStart} onChange={(event) => onScheduleTimesChange({ ...scheduleTimes, dayStart: event.target.value })} /></label><label><span>Seara începe</span><input type="time" value={scheduleTimes.eveningStart} onChange={(event) => onScheduleTimesChange({ ...scheduleTimes, eveningStart: event.target.value })} /></label><label><span>Noaptea începe</span><input type="time" value={scheduleTimes.nightStart} onChange={(event) => onScheduleTimesChange({ ...scheduleTimes, nightStart: event.target.value })} /></label></div>{!scheduleIsValid && <small className="bf-theme-schedule-error">Ordinea trebuie să fie zi → seară → noapte. Până la corectare se folosesc temporar valorile standard: 06:00, 17:00 și 21:00.</small>}<button className={highContrast ? "active" : ""} role="switch" aria-checked={highContrast} onClick={() => onContrastChange(!highContrast)}><span><b>Contrast extra-ridicat</b><small>Contururi, texte secundare și stări active mai puternice, fără a schimba culorile banilor.</small></span><i aria-hidden="true" /></button></section><button className="bf-theme-apply" onClick={applyPreview}><Check size={17} /> Aplică {previewOption.name}</button></section></div>;
}

